sys_script_include.script:
var SkillNowFilters = Class.create();
SkillNowFilters.prototype = {
    initialize: function() {},

    getAvailableSchedules: function() {
        var user = gs.getUserID();


        var filter = 'active=true^training_date>javascript:gs.daysAgo(-1)';

        filter += '^instructor!=' + user;


        var coursesToExclude = this._getCoursesExceedingLimit(user);
        if (coursesToExclude.length > 0) {
            filter += '^courseNOT IN' + coursesToExclude.join(',');
        }


        var fullSchedules = this._getFullSchedules();
        if (fullSchedules.length > 0) {
            filter += '^sys_idNOT IN' + fullSchedules.join(',');
        }


        var alreadyEnrolled = this._getAlreadyEnrolled(user);
        if (alreadyEnrolled.length > 0) {
            filter += '^sys_idNOT IN' + alreadyEnrolled.join(',');
        }

        return filter;
    },

    _getCoursesExceedingLimit: function(userId) {
        var excludedCourses = [];
        var courseCounts = {};

        var enr = new GlideRecord('x_1974477_skillnow_enrollment');
        enr.addQuery('opened_by', userId);
        enr.query();

        while (enr.next()) {

            var courseId = enr.schedule.course.toString(); 
            if (courseId) {
                courseCounts[courseId] = (courseCounts[courseId] || 0) + 1;
                if (courseCounts[courseId] >= 3) {
                    excludedCourses.push(courseId);
                }
            }
        }
        return excludedCourses;
    },

	_getFullSchedules: function() {
        var full = [];
        var scheduleGR = new GlideRecord('x_1974477_skillnow_training_schedule');
        scheduleGR.addActiveQuery(); 
        scheduleGR.query();

        while (scheduleGR.next()) {
            var schedID = scheduleGR.getUniqueValue();


            var capacity = parseInt(scheduleGR.getValue('slots'), 10);


            if (isNaN(capacity) || capacity <= 0) {
                continue;
            }


            var enrollmentGR = new GlideRecord('x_1974477_skillnow_enrollment');
            enrollmentGR.addQuery('schedule', schedID);
            enrollmentGR.query();
            var currentCount = enrollmentGR.getRowCount();



            if (currentCount >= capacity) {
                full.push(schedID);
            }
        }
        return full;
    },

    _getAlreadyEnrolled: function(userId) {
        var ids = [];
        var enr = new GlideRecord('x_1974477_skillnow_enrollment');
        enr.addQuery('opened_by', userId);
        enr.query();
        while (enr.next()) {
            ids.push(enr.getValue('schedule'));
        }
        return ids;
    },

    type: 'SkillNowFilters'
};
